import{c as e,Q as r,j as d,m as a}from"./chunks/framework.rWdQudnF.js";const b=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-计算机组成-存储系统","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-计算机组成-存储系统"},"headers":[],"relativePath":"综合知识/系统基础/计算机组成/存储与IO系统/存储系统.md","filePath":"综合知识/系统基础/计算机组成/存储与IO系统/存储系统.md","lastUpdated":null}'),o={name:"综合知识/系统基础/计算机组成/存储与IO系统/存储系统.md"};function n(l,t,s,h,g,c){return r(),d("div",null,[...t[0]||(t[0]=[a('<h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="存储系统-★" tabindex="-1">存储系统 ★ <a class="header-anchor" href="#存储系统-★" aria-label="Permalink to &quot;存储系统 ★&quot;">​</a></h3><h4 id="分级存储" tabindex="-1">分级存储 <a class="header-anchor" href="#分级存储" aria-label="Permalink to &quot;分级存储&quot;">​</a></h4><blockquote><p>目的：解决存储<strong>容量、成本和速度</strong>之间的矛盾。按 CPU 物理距离分 4 层（由近→远）：片上缓存 → 片外缓存 → 主存（内存）→ 外存。速度依次降低，容量依次提高。</p></blockquote><p><strong>两级存储</strong>：Cache-主存、主存-辅存（虚拟存储体系）。</p><p><strong>局部性原理</strong>：</p><ul><li><strong>时间局部性</strong>：刚被访问的数据近期可能再次被访问</li><li><strong>空间局部性</strong>：相邻地址的数据可能被连续访问</li></ul><blockquote><p>🎯 一句话结论：<strong>局部性原理不仅适用于循环程序</strong>，数组访问（空间局部性）、子程序调用等也体现局部性。Cache 设计的理论依据正是程序的局部性原理。</p></blockquote><h4 id="相联存取-按内容寻址-★" tabindex="-1">相联存取（按内容寻址）★ <a class="header-anchor" href="#相联存取-按内容寻址-★" aria-label="Permalink to &quot;相联存取（按内容寻址）★&quot;">​</a></h4><blockquote><p>🎯 一句话结论：<strong>相联存取根据访问内容（而非地址）决定存储单元</strong>，常用于 <strong>Cache</strong> 中。</p></blockquote><table tabindex="0"><thead><tr><th>存取方式</th><th>机制</th><th>应用</th></tr></thead><tbody><tr><td>顺序存取</td><td>按顺序定位数据</td><td>磁带</td></tr><tr><td>直接存取</td><td>直接定位到块，再顺序查找</td><td>磁盘</td></tr><tr><td>随机存取</td><td>按地址直接访问任意单元</td><td>主存（DRAM）</td></tr><tr><td><strong>相联存取</strong></td><td><strong>按内容而非地址</strong>查找</td><td><strong>Cache</strong>（TLB也用到）</td></tr></tbody></table><blockquote><p>相联存取能在一个存储周期内将关键字与所有单元同时比较，硬件复杂度高但速度快。</p></blockquote><h4 id="存储介质易失性分类" tabindex="-1">存储介质易失性分类 <a class="header-anchor" href="#存储介质易失性分类" aria-label="Permalink to &quot;存储介质易失性分类&quot;">​</a></h4><blockquote><p>🎯 一句话结论：<strong>SRAM/DRAM/寄存器 掉电丢失数据（易失性），Flash/SSD/HDD/ROM 掉电保持数据（非易失性）</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>介质</th><th style="text-align:center;">易失性</th><th style="text-align:center;">速度</th><th>典型用途</th></tr></thead><tbody><tr><td>寄存器</td><td>触发器</td><td style="text-align:center;">易失</td><td style="text-align:center;"><strong>最快</strong></td><td>CPU 内部</td></tr><tr><td>SRAM</td><td>晶体管</td><td style="text-align:center;">易失</td><td style="text-align:center;">很快</td><td>Cache（L1/L2/L3）</td></tr><tr><td>DRAM</td><td>电容</td><td style="text-align:center;">易失（需刷新）</td><td style="text-align:center;">中</td><td>主存（内存条）</td></tr><tr><td>Flash</td><td>浮栅晶体管</td><td style="text-align:center;"><strong>非易失</strong></td><td style="text-align:center;">慢于DRAM</td><td>SSD、U盘</td></tr><tr><td>HDD</td><td>磁介质</td><td style="text-align:center;"><strong>非易失</strong></td><td style="text-align:center;"><strong>最慢</strong></td><td>机械硬盘</td></tr></tbody></table><blockquote><p>⚠️ <strong>DRAM 访问速度远高于 SSD/HDD</strong>，常见干扰项说&quot;DRAM 速度远低于 SSD&quot;是错误的。</p></blockquote><h4 id="dram-与-ddr-sdram-特性" tabindex="-1">DRAM 与 DDR SDRAM 特性 <a class="header-anchor" href="#dram-与-ddr-sdram-特性" aria-label="Permalink to &quot;DRAM 与 DDR SDRAM 特性&quot;">​</a></h4><blockquote><p>🎯 一句话结论：<strong>DDR SDRAM 在时钟上升沿和下降沿各传输一次数据</strong>，同等时钟频率下带宽是普通 SDRAM 的 2 倍。</p></blockquote><ul><li>DRAM 用电容存储，需<strong>定时刷新</strong>以保持数据</li><li>DDR（Double Data Rate）：<strong>时钟上下沿都传输</strong>，实现加倍速率</li><li>速度链：CPU 寄存器 &gt; Cache(SRAM) &gt; 主存(DRAM) &gt; SSD(Flash) &gt; HDD(磁盘)</li></ul><h4 id="cache-地址映射-★" tabindex="-1">Cache 地址映射 ★ <a class="header-anchor" href="#cache-地址映射-★" aria-label="Permalink to &quot;Cache 地址映射 ★&quot;">​</a></h4><blockquote><p>在 CPU 工作时，送出的是主存地址，需转换为 Cache 地址，称为<strong>地址映像</strong>，由<strong>硬件自动完成</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>映射方式</th><th>特点</th><th style="text-align:center;">块冲突概率</th></tr></thead><tbody><tr><td><strong>直接映像</strong></td><td>主存块与 Cache 块号相同才能命中，变换简单但不灵活</td><td style="text-align:center;"><strong>最高</strong></td></tr><tr><td><strong>全相联映像</strong></td><td>主存任意块可调入 Cache 任意块，变换复杂速度慢</td><td style="text-align:center;"><strong>最低</strong></td></tr><tr><td><strong>组相联映像</strong></td><td>组间直接映像 + 组内全相联映像，前两者折中</td><td style="text-align:center;">中</td></tr></tbody></table><blockquote><p>块冲突概率：<strong>直接映像 &gt; 组相联映像 &gt; 全相联映像</strong>。</p></blockquote><h4 id="替换算法" tabindex="-1">替换算法 <a class="header-anchor" href="#替换算法" aria-label="Permalink to &quot;替换算法&quot;">​</a></h4><table tabindex="0"><thead><tr><th>算法</th><th>说明</th></tr></thead><tbody><tr><td>随机替换</td><td>随机选择被替换块</td></tr><tr><td>先进先出（FIFO）</td><td>替换最先进入 Cache 的块</td></tr><tr><td><strong>近期最少使用（LRU）</strong></td><td>替换近期最少使用的块</td></tr><tr><td>优化替换</td><td>先执行一次程序统计替换情况，第二次用最优方式</td></tr></tbody></table><h4 id="命中率计算" tabindex="-1">命中率计算 <a class="header-anchor" href="#命中率计算" aria-label="Permalink to &quot;命中率计算&quot;">​</a></h4><blockquote><p>平均访问时间 = 命中率 × Cache 访问时间 +（1 - 命中率）× 主存访问时间。</p></blockquote><h4 id="磁盘结构与调度算法-★" tabindex="-1">磁盘结构与调度算法 ★ <a class="header-anchor" href="#磁盘结构与调度算法-★" aria-label="Permalink to &quot;磁盘结构与调度算法 ★&quot;">​</a></h4><p><strong>磁盘三大要素</strong>：磁头（Head）、柱面（Cylinder，所有盘面同位置磁道集合）、扇区（Sector，最小存储单元）。</p><table tabindex="0"><thead><tr><th>算法</th><th>说明</th><th>特点</th></tr></thead><tbody><tr><td><strong>FCFS</strong>（先来先服务）</td><td>按请求顺序调度</td><td>公平但效率低</td></tr><tr><td><strong>SSTF</strong>（最短寻道时间优先）</td><td>离当前磁道最近的请求优先</td><td>可能产生&quot;<strong>饥饿</strong>&quot;</td></tr><tr><td><strong>SCAN</strong>（扫描/电梯算法）</td><td>磁头双向移动到底才掉头</td><td>与电梯类似</td></tr><tr><td><strong>CSCAN</strong>（单向扫描）</td><td>只做单向移动</td><td>更均匀的等待时间</td></tr></tbody></table>',30)])])}const u=e(o,[["render",n]]);export{b as __pageData,u as default};
